class Solution:
    def runningBalance(self, changes: List[int]) -> List[int]:
        out = []
        for i in range(len(changes)):
            total = 0
            for k in range(i + 1):
                total += changes[k]
            out.append(total)
        return out

code.java:
class Solution {
    public int[] runningBalance(int[] changes) {
        int n = changes.length;
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            int total = 0;
            for (int k = 0; k <= i; k++) total += changes[k];
            out[i] = total;
        }
        return out;
    }
}

